int
print_ipv6_routing_header(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ipv6_routing_header *rh;
    int len, i;
    u_int nh, hdrlen;

    rh = (const struct ipv6_routing_header *)bp;
    len = sizeof(struct ipv6_routing_header);
    if (len > ndo->ndo_snaplen) {
        ND_PRINT((ndo, " [truncated]"));
        return (-1);
    }
    ND_PRINT((ndo, "\n\t  Routing Header, type %u, segments left %u, length %u",
              rh->rh_type, rh->rh_seg_left, rh->rh_len * 8));

    hdrlen = (rh->rh_len * 8) + 8;
    if (hdrlen > ndo->ndo_snaplen) {
        ND_PRINT((ndo, " [truncated]"));
        return (-1);
    }

    switch (rh->rh_type) {
        case 0:
            for (i = 0; i <= rh->rh_seg_left; i++) {
                ND_PRINT((ndo, "\n\t    %s", ip6addr_string(ndo, &rh->rh_addrs[i])));
            }
            break;
        default:
            ND_PRINT((ndo, "\n\t    [unknown routing type %u]",
                      rh->rh_type));
            break;
    }

    return (hdrlen);
}

int
print_ipv6_routing_header(netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ip6_rthdr *rthdr;
    int len, hdrlen, i;
    u_int segments;

    rthdr = (const struct ip6_rthdr *)bp;

    if (rthdr->ip6r_len > (ND_DEFAULT_SNAPLEN - (bp - rthdr->ip6r_hdr)))
        return (-1);

    hdrlen = rthdr->ip6r_len + sizeof(*rthdr);
    len = hdrlen;

    ND_PRINT((ndo, "Routing Header: length = %u, type = %u", rthdr->ip6r_len, rthdr->ip6r_type));

    segments = rthdr->ip6r_segleft;
    ND_PRINT((ndo, ", segments left = %u", segments));

    switch (rthdr->ip6r_type) {
        case 0: // Type 0, simple routing header
            if (segments > 0) {
                const struct in6_addr *addrs;
                addrs = (const struct in6_addr *)((const u_char *)rthdr + sizeof(*rthdr));

                for (i = 0; i < segments; i++) {
                    if (addrs + i >= (const struct in6_addr *)((const u_char *)rthdr + hdrlen))
                        break;
                    ND_PRINT((ndo, "\n\tAddress %d: %s", i + 1, ip6addr_string(ndo, &addrs[i])));
                }

                if (i < segments) {
                    ND_PRINT((ndo, "\n\t[Truncated]"));
                    return (-1);
                }
            }
            break;
        default:
            ND_PRINT((ndo, "\n\t[Unknown routing header type]"));
            break;
    }

    return (len);
}

int print_ipv6_routing_header(struct netdissect_options *ndo, const u_char *bp, const u_char *bp2) {
    const struct ip6_rthdr *rh;
    int i;
    u_int len, hdrlen;
    int off = 0;

    if ((v6print) == NULL)
        v6print = ndo->ndo_snapend;

    rh = (struct ip6_rthdr *)bp;
    hdrlen = sizeof(struct ip6_rthdr);

    ND_PRINT("\n\t  routing type %d, length %d, segments left %d\n",
             rh->ip6r_nxt, rh->ip6r_len * 8, rh->ip6r_segleft);

    len = 0;
    switch (rh->ip6r_nxt) {
        case IPPROTO_DSTOPTS:
        case IPPROTO_ROUTING:
            len = 8;
            break;
        default:
            len = 0;
            break;
    }

    for (i = 0; i < rh->ip6r_segleft; i++) {
        if (off + sizeof(struct in6_addr) > hdrlen) {
            ND_PRINT("\n\t  [truncated]");
            return -1;
        }
        ND_PRINT("\n\t  %s", ip6addr_string(ndo, (const u_char *)&rh[1 + i]));
        off += sizeof(struct in6_addr);
    }

    return hdrlen;
}

int
print_ipv6_routing_header(struct netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ip6_rthdr *rthdr;
    int len;
    int i;

    rthdr = (const struct ip6_rthdr *)bp;

    ND_PRINT("(Routing) ");

    if (rthdr->ip6r_len == 0) {
        ND_PRINT("Routing header length is zero");
        return 0;
    }

    len = (rthdr->ip6r_len + 1) * 8;

    if (len > 0 && bp + len > bp2) {
        ND_PRINT("[|trunc]");
        return -1;
    }

    ND_PRINT("Routing Type: %u, Segments Left: %u, Header Length: %u bytes",
             rthdr->ip6r_type, rthdr->ip6r_segleft, len);

    if (rthdr->ip6r_type == 0) {
        int num_addrs = rthdr->ip6r_segleft;
        const u_char *addrp = (const u_char *)(rthdr + 1);

        for (i = 0; i < num_addrs; i++) {
            if (addrp + sizeof(struct in6_addr) > bp2) {
                ND_PRINT("[|trunc]");
                return -1;
            }

            ND_PRINT("Address[%d]: %s", i, ip6addr_string(ndo, (const struct in6_addr *)addrp));
            addrp += sizeof(struct in6_addr);
        }
    }

    return len;
}
